/* per-device views of the data */
function jobsOf(st){var base=st.fresh?[]:JOBS;var list=base.concat(st.created||[]).map(clone);var ov=st.ov||{};
 list.forEach(function(j){var o=ov[j.id];if(!o)return;['status','instr','pdf','days','team','price'].forEach(function(k){if(o[k]!=null)j[k]=o[k];});if(o.pays)j.pays=j.pays.concat(o.pays);if(o.mats)j.mats=j.mats.concat(o.mats);if(o.rooms)j.rooms=o.rooms;if(o.photos)j.photos=o.photos;});return list;}
function job(st,id){var l=jobsOf(st);for(var i=0;i<l.length;i++)if(l[i].id===id)return l[i];return l[0]||null;}
function updsOf(st){var base=st.fresh?[]:UPDATES;var seen=st.seen||{};return base.concat(st.newU||[]).map(function(u){var x=clone(u);if(seen[u.id])x.seen=true;return x;});}
function paid(j){return j.pays.reduce(function(s,p){return s+p.a;},0);}
function owed(j){return Math.max(0,(j.price||0)-paid(j));}
function area(rooms){return rooms.reduce(function(s,r){return s+(r.a?+r.a:(+r.l)*(+r.w));},0);}
function statusPill(j){var s=STATUS[j.status];if(j.status==='done'&&owed(j)===0)return pill('Completed · paid','green','check');return pill(s[0],s[1],s[2]);}
function dayN(j,k){var i=j.days?j.days.indexOf(k):-1;return i<0?'':'Day '+(i+1)+' of '+j.days.length;}
function teamNames(t){return (t||[]).map(function(p){return STAFF[p].n;}).join(', ');}
function dateRange(d){if(!d||!d.length)return 'Not booked yet';return d.length===1?dayLabel(d[0]):dayLabel(d[0])+' – '+dayLabel(d[d.length-1]);}
var NAV=[['today','Today'],['calendar','Calendar'],['jobs','Jobs'],['customers','Customers'],['hours','Hours & updates'],['money','Money']];
function office(ctx,active,title,inner,o){o=o||{};o.who='Milen · Owner';var n=NAV.map(function(x){return x.slice();});var un=updsOf(ctx.st).filter(function(u){return !u.seen;}).length;if(un)n[4][2]=un;return webPage(ctx,n,active,title,inner,o);}

