 var chips='<div class="ap-chips">'+[['open','Open'],['enquiry','New enquiries'],['visit','Site visits'],['quoted','Quotes sent'],['booked','Booked'],['progress','In progress'],['done','Completed'],['all','All']].map(function(c){var n=c[0]==='all'?jobs.length:c[0]==='open'?jobs.filter(function(j){return j.status!=='done';}).length:jobs.filter(function(j){return j.status===c[0];}).length;return chip(c[1]+' · '+n,f===c[0],'data-act="set" data-arg="jf='+c[0]+'"');}).join('')+'</div>';
 var rows=jobs.filter(function(j){return f==='all'||(f==='open'?j.status!=='done':j.status===f);}).sort(function(a,b){return STATUS_ORDER.indexOf(a.status)-STATUS_ORDER.indexOf(b.status);});
 var t=rows.length?'<div class="ap-tw"><table class="ap-t"><thead><tr><th>Customer</th><th>Work</th><th>Dates</th><th>Team</th><th>Status</th></tr></thead><tbody>'+rows.map(function(j){return '<tr class="click" data-act="go" data-arg="job" data-set="jid='+j.id+'"><td><b>'+esc(j.cust)+'</b><span class="m">'+esc(j.addr)+'</span></td><td>'+esc(j.work)+'</td><td>'+(j.days&&j.days.length?dateRange(j.days):(j.visit?'Visit '+esc(j.visit):'–'))+'</td><td>'+esc(teamNames(j.team)||'–')+'</td><td>'+statusPill(j)+'</td></tr>';}).join('')+'</tbody></table></div>':emptyBox('list','No jobs here','Try another filter, or add a new enquiry.');
