/* ===== actions ===== */
function ovr(st,id){st.ov=st.ov||{};st.ov[id]=st.ov[id]||{};return st.ov[id];}
var ACT={
 setpw:function(st,a,inst){var p1=st.p1||'',p2=st.p2||'';if(p1.length<8){st.err='Use at least 8 letters or numbers.';return;}if(p1!==p2){st.err="The two passwords don't match.";return;}st.err=null;inst.stack=['myjobs'];},
 jobStatus:function(st,a){var id=st.jid||(function(){var u=null;updsOf(st).forEach(function(x){if(x.id===st.uid)u=x;});return u&&u.job;})();ovr(st,id).status=a;st.toast='Status: '+STATUS[a][0];},
 editBooking:function(st){st.editBk=true;st.bkd=null;},
 bkTeam:function(st,a){var d=st.bkd;var i=d.team.indexOf(a);if(i>=0)d.team.splice(i,1);else d.team.push(a);},
 saveBk:function(st){var d=st.bkd;if(!/^\d{4}-\d{2}-\d{2}$/.test(d.start))return;var days=[];for(var i=0;i<+d.n;i++)days.push(addDays(d.start,i));var o=ovr(st,st.jid);o.days=days;o.team=d.team.slice();var j=job(st,st.jid);if(j.status==='enquiry'||j.status==='visit'||j.status==='quoted')o.status='booked';st.editBk=false;st.toast='Booked. '+teamNames(d.team)+' can see it now.';},
 saveIns:function(st){if(st.insDraft!=null)ovr(st,st.jid).instr=st.insDraft;st.editIns=false;st.toast='Instructions saved';},
 addMat:function(st){if(!st.mat)return;var o=ovr(st,st.jid);o.mats=(o.mats||[]).concat([st.mat]);st.mat='';},
 attachQuote:function(st){var j=job(st,st.jid);ovr(st,st.jid).pdf='Quote-'+j.cust.split(' ').pop()+'.pdf';st.toast='Quote attached';},
 setPrice:function(st){var p=parseFloat(st.newPrice);if(!(p>0)){st.toast='Type the price, like 1250.00';return;}ovr(st,st.jid).price=r2(p);st.newPrice='';},
 pay:function(st){var j=job(st,st.jid);var a=parseFloat(st.payA!=null?st.payA:owed(j));if(!(a>0)){st.payErr='Type the amount, like 500.00.';return;}if(a>owed(j)+0.001){st.payErr='That\'s more than the '+eur(owed(j))+' still owed.';return;}var o=ovr(st,st.jid);o.pays=(o.pays||[]).concat([{d:TODAY,a:r2(a),m:st.payM||'Bank transfer'}]);st.payA=null;st.payErr='';st.sheet=null;st.toast='Payment of '+eur(a)+' saved';},
 seen:function(st){st.seen=st.seen||{};st.seen[st.uid]=true;st.toast='Marked as seen';},
 saveEnq:function(st,a,inst){var e=st.ne||{};if(!e.cust||(!e.phone&&!e.email)||!e.work){st.tried=true;return;}var id='n'+((st.created||[]).length+1);var vis=e.vday?(e.vday+(e.vtime?', '+e.vtime:'')):'';
  st.created=(st.created||[]).concat([{id:id,cust:e.cust,phone:e.phone||'',email:e.email||'',addr:e.addr||'',work:e.work,status:vis?'visit':'enquiry',visit:vis,visitDay:vis?'2026-10-22':'',visitTime:e.vtime||'',price:0,pays:[],rooms:[],photos:[],mats:[],instr:e.notes||''}]);st.ne={};st.tried=false;st.jid=id;st.toast='Enquiry saved';inst.stack[inst.stack.length-1]='job';},
 saveRoom:function(st){var d=st.dr||{};if(!d.n){st.rErr='Add a room name.';return;}if(!drArea(d)){st.rErr='Add the length and width, or the area.';return;}st.vr.push({n:d.n,l:d.l||'',w:d.w||'',a:d.a||'',t:d.t||'Sanding'});st.dr={};st.addR=false;st.rErr='';},
 vPhoto:function(st){st.vp.push({l:'New photo',w:1});},
 visitDone:function(st,a,inst){var o=ovr(st,st.jid||'j8');o.rooms=st.vr.map(function(r){return (+r.l>0&&+r.w>0)?{n:r.n,l:+r.l,w:+r.w}:{n:r.n,l:0,w:0,a:+r.a};});o.photos=st.vp.map(function(p){return p.l;});st.toast='Site visit saved to the job';if(inst.stack.length>1)inst.stack.pop();},
 openPh:function(st,a){st.sheet='photo';st.phI=a;},
 hStep:function(st,a){var d=st.ud;d.h=Math.max(0,Math.min(14,d.h+parseFloat(a)));},
 uPhoto:function(st){st.ud.photos.push({l:'Progress',w:st.mode==='offline'?1:0});},
 toggleFin:function(st){st.ud.fin=!st.ud.fin;},
 sendUpd:function(st,a,inst){var d=st.ud;if(!d.done||!d.h){st.tried=true;return;}var u={id:'nu'+((st.newU||[]).length+1),job:st.jid||'j1',who:ME,date:TODAY,h:d.h,done:d.done,issue:d.issue,photos:d.photos.map(function(p){return p.l;}),seen:false,fin:d.fin};st.newU=(st.newU||[]).concat([u]);st.ud=null;st.tried=false;st.toast=st.mode==='offline'?'Saved on your phone. It sends when you\'re back online.':'Update sent to Milen';inst.stack.pop();}
};
